import sys

def solve():
    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data)

    MOD = 998244353

    if n == 1:
        print(1)
        return

    fact = 1
    for k in range(1, n + 1):
        fact = (fact * k) % MOD

    total_len = (n * fact) % MOD

    ans = 0

    for k in range(1, n + 1):
        if k == 1:
            term = n
        else:
            ways = 0
            if k < n:
                term1 = (n - k + 1) % MOD
                term2 = 1
                for x in range(1, k):
                    term2 = (term2 * x) % MOD
                ways = (term1 * term2) % MOD
            elif k == n:
                ways = 1
            else:
                ways = 0

            count = 0
            if k < n:
                count = (n - k + 1) % MOD
                for x in range(1, k):
                    count = (count * x) % MOD
            elif k == n:
                count = 1
            else:
                count = 0

            block_len = k
            full_blocks = total_len // block_len
            remainder = total_len % block_len

            occ = (full_blocks * count) % MOD
            if remainder >= block_len:
                occ = (occ + count) % MOD

            term = (ways * occ) % MOD

        ans = (ans + term) % MOD

    print(ans)

if __name__ == "__main__":
    solve()
